import React, { useRef, useEffect, useState } from 'react';
import { Canvas, useFrame } from '@react-three/fiber'; // Correctly import useFrame
import { OrbitControls, AsciiRenderer } from '@react-three/drei';
import { STLLoader } from 'three/examples/jsm/loaders/STLLoader';
import * as THREE from 'three';

export default function App() {
  const [useAscii, setUseAscii] = useState(true); // State to toggle ASCII rendering

  return (
    <div style={{ height: '100vh', width: '100vw', background: '#000' }}>
      {/* Toggle Button */}
      <button
        style={{
          position: 'absolute',
          top: '20px',
          left: '20px',
          zIndex: 1,
          padding: '10px 20px',
          backgroundColor: '#333',
          color: '#fff',
          border: 'none',
          cursor: 'pointer',
          fontSize: '16px',
        }}
        onClick={() => setUseAscii(!useAscii)}
      >
        {useAscii ? 'Switch to 3D View' : 'Switch to ASCII View'}
      </button>

      <Canvas
        camera={{ position: [0, 0, 15], fov: 45 }}
        style={{ width: '100%', height: '100%' }}
      >
        <color attach="background" args={['#000']} />
        <OrbitControls />
        <ambientLight intensity={0.8} />
        <directionalLight position={[5, 5, 5]} intensity={1} />
        {/* Placeholder Model or STL Viewer */}
        <STLViewer path="./stls/model.stl" />
        {useAscii && <AsciiRenderer invert />}
      </Canvas>
    </div>
  );
}

// Component to load and display the STL file or a placeholder
function STLViewer({ path }) {
  const [geometry, setGeometry] = useState(null);
  const meshRef = useRef();

  useEffect(() => {
    const loader = new STLLoader();
    loader.load(
      path,
      (geometry) => {
        geometry.center(); // Center the model in the scene
        scaleGeometryToFit(geometry, 5); // Scale to fit within a 5-unit bounding box
        setGeometry(geometry);
      },
      (xhr) => {
        // Optional: Track loading progress
        console.log(`Loading STL: ${(xhr.loaded / xhr.total) * 100}%`);
      },
      (error) => {
        console.error('Error loading STL:', error);
        setGeometry(null); // Display placeholder if the STL fails to load
      }
    );
  }, [path]);

  if (!geometry) {
    return <PlaceholderModel />; // Show placeholder if the model is not loaded
  }

  return (
    <mesh ref={meshRef} geometry={geometry}>
      <meshStandardMaterial color="#00ffff" wireframe={false} />
    </mesh>
  );
}

// Function to scale the geometry so that its largest dimension fits within the max size
function scaleGeometryToFit(geometry, maxSize) {
  // Compute the bounding box of the geometry
  const box = new THREE.Box3().setFromObject(new THREE.Mesh(geometry));
  const size = box.getSize(new THREE.Vector3());

  // Find the largest dimension
  const maxDim = Math.max(size.x, size.y, size.z);

  // Scale the geometry to fit within the maxSize
  const scaleFactor = maxSize / maxDim;
  geometry.scale(scaleFactor, scaleFactor, scaleFactor);
}

// Placeholder Model: A rotating box
function PlaceholderModel() {
  const meshRef = useRef();

  // Rotate the placeholder model continuously using useFrame
  useFrame(() => {
    if (meshRef.current) {
      meshRef.current.rotation.x += 0.01;
      meshRef.current.rotation.y += 0.01;
    }
  });

  return (
    <mesh ref={meshRef}>
      <boxGeometry args={[2, 2, 2]} />
      <meshStandardMaterial color="gray" wireframe />
    </mesh>
  );
}
